\begin{lemma} \label{lem:norm_naturality}
	\uses{def:norm}
	\lean{Rep.norm_comm,
		Rep.normNatTrans}
	\leanok
	\mathlibok
	For every map $f : A \to B$ in $\mathbf{Rep}(R,G)$ we have a commuting square:
	\[
		\begin{array}{rcl}
			A & \stackrel{f}\to & B \\[2mm]
			N_G\downarrow && \downarrow N_G \\
			A & \stackrel{f}\to & B
		\end{array} .
	\]
	Equivalently, $N_G$ is an endomorphism of the forgetful functor $\mathbf{Rep}(R,G) \to \mathbf{Mod}(R)$.
\end{lemma}

n31815.content:
\begin{definition} \label{def:trivial_cohomology}
	\lean{Rep.TrivialCohomology,
		Rep.TrivialHomology,
		Rep.TrivialTateCohomology}
	\uses{def:group_homology, def:inflation_restriction_functors}
	\leanok
	Let $M$ be a representation of $G$ over a ring $R$.
	\begin{itemize}
		\item
		$M$ is said to have \emph{trivial cohomology} if for every subgroup $S \le G$
		and every $n > 0$, $H^n(S,M) \cong 0$.
		\item
		$M$ is said to have \emph{trivial homology} if for every subgroup $S \le G$
		and every $n > 0$, $H_n(S,M) \cong 0$.
		\item
		Suppose the group $G$ is finite. Then $M$ is said to have \emph{trivial Tate cohomology}
		if for every subgroup $S \le G$
		and every $n \in {\mathbb Z}$, $H^n_{\mathrm{Tate}}(S,M) \cong 0$.
	\end{itemize}
	(We will later see that for a finite group $G$, the three concepts are equivalent.)
\end{definition}

