n31851.content:
\begin{theorem}
	\label{thm:inflation_restriction_sequence}
	\lean{groupCohomology.inflationRestriction,
		groupCohomology.inflation_restriction_mono,
		groupCohomology.inflation_restriction_exact}
	\uses{def:up, cor:coind₁'_invariants_trivial_cohomology, lem:inflation_restriction_naturality}
	\leanok
	Let $S$ be a normal subgroup of a group $G$ and let $n$ be a positive integer.
	Assume that for all natural numbers $0 <i < n$ we have $H^{i}(S,M) \cong 0$.
	Then the following sequence is exact:
	\[
		0 \to H^{n}(G/S, M^S) \to H^{n}(G,M) \to H^{n}(S,M),
	\]
	where the first map is inflation and the second is restriction.
\end{theorem}

n31854.content:
\begin{lemma} \label{lem:cor_comp_rest}
	\uses{def:corestriction, lem:inflation_restriction_naturality}
	For all $\sigma \in H^n(G,M)$ we have
	\(\mathrm{cor}(\mathrm{rest}(\sigma)) = [G:S] \cdot \sigma\).
\end{lemma}

n31856.content:
\begin{corollary} \label{cor:cohomology_G-torsion}
	\uses{lem:cor_comp_rest, lem:Hn_unit, lem:Tate_cohomology_is_cohomology_or_homology, cor:Tate_up_down_isos}
	If $M$ is a representation of a finite group $G$ then for
	all $n \in {\mathbb Z}$ and all $\sigma \in H^n_{\mathrm{Tate}}(G,M)$ we have $|G| \cdot \sigma = 0$.
\end{corollary}

n31857.content:
\begin{proof}
	By dimension-shifting (\ref{cor:Tate_up_down_isos}) it's enough to prove the result for $n > 0$,
	in which case by \ref{lem:Tate_cohomology_is_cohomology_or_homology}
	Tate cohomology is isomorphic to cohomology.
	Take $S$ to be the trivial subgroup $1$ of $G$.
	By \ref{lem:cor_comp_rest} it's sufficient to prove that $\mathrm{cor}(\mathrm{rest}(\sigma))= 0$.
	This follows because $\mathrm{rest}(\sigma) \in H^n(1,M) \cong 0$ by \ref{lem:Hn_unit}.
\end{proof}

n31858.content:
\begin{corollary} \label{cor:cohomology_sub_Sylow}
	\uses{cor:Tate_up_down_isos, lem:Tate_cohomology_is_cohomology_or_homology, lem:cor_comp_rest}
	Let $M$ be a representation of a finite group $G$ and let $S_p$ be a Sylow $p$-subgroup of $G$
	for some prime number $p$.
	Then for any $n \in {\mathbb Z}$, $H^n_{\mathrm{Tate}}(G,M)[p^\infty]$ is isomorphic to an $R$-submodule
	of $H^n_{\mathrm{Tate}}(S_p,M)$.
\end{corollary}

n31860.content:
\begin{lemma} \label{lem:map2_image}
	\lean{Representation.map₂_range}
	\uses{def:ind'}
	\leanok
	The image of $\mathrm{map}_2 : \mathrm{ind}_1'(M) \to \mathrm{ind}_1'(M)$ is precisely the set of functions $G \to_0 M$
	which sum to zero. This is the kernel of the map $\mathrm{ind}_1'(M) \to M$,
	which we are calling $\mathrm{down}(M)$.
\end{lemma}

n31861.content:
\begin{proof}
	\leanok
	It's clear that the values of $\mathrm{map}_2(f)$ sum to $0$, so the image of $\mathrm{map}_2$ is contained in
	the kernel.
	Conversely suppose $h : G \to_0 M$ satisfies $\sum_{i=0}^{n-1} h(\mathrm{gen}^i) = 0$.
	Then we have
	\begin{align*}
		h
		& = \sum_{i=0}^{n-1} \mathrm{single}(\mathrm{gen}^i, h(\mathrm{gen}^i))\\
		& = \sum_{i=0}^{n-1} (\mathrm{single}(\mathrm{gen}^i, h(\mathrm{gen}^i)) - \mathrm{single}(1, h(\mathrm{gen}^i))).
	\end{align*}
	Furthermore each of the terms $\mathrm{single}(\mathrm{gen}^i, m) - \mathrm{single}(1, m)$ is in the
	image of $\mathrm{map}_2$:
	\begin{align*}
		\mathrm{map}_2 (\mathrm{single}(1,m) + \cdots + \mathrm{single}(\mathrm{gen}^{i-1},m))
		&=\mathrm{single}(1,m) - \mathrm{single}(\mathrm{gen}^i,m).
	\end{align*}
\end{proof}

n31863.content:
\begin{corollary} \label{cor:periodic_cohomology}
	\uses{cor:Tate_up_down_isos, def:up_iso_down}
	\lean{Rep.periodicCohomology, periodicTateCohomology}
  \leanok
	Let $G$ be a finite cyclic group.
	For all $n > 0$ and all representations $M$
	we have an isomorphism $H^{n}(G,M) \cong H^{n+2}(G,M)$.
	Similarly for all integers $n$ we have isomorphisms $H^{n}_{\mathrm{Tate}}(G,M) \cong H^{n+2}_{\mathrm{Tate}}(G,M)$.
\end{corollary}

n31864.content:
\begin{proof}
  \leanok
	By the dimension-shifting isomorphisms we have
	$H^{n}(G,M) \cong H^{n+1}(G,\mathrm{down}(M)) \cong H^{n+1}(G,\mathrm{up}(M)) \cong H^{n+2}(G,M)$,
	and similarly for Tate cohomology.
\end{proof}

n31865.content:
\begin{lemma} \label{lem:H2_cyclic_Z}
	\uses{cor:periodic_cohomology}
	\lean{groupCohomology.evenTrivialInt, groupCohomology.isZero_odd_trivial_of_isAddTorsionFree}
	\leanok

	Let $G$ be a finite cyclic group of order $n$.
	Then $H^1(G,{\mathbb Z}) \cong 0$ and $H^2(G,{\mathbb Z}) \cong {\mathbb Z}/n{\mathbb Z}$.
\end{lemma}

n31866.content:
\begin{proof}
	\leanok

	Since the module ${\mathbb Z}$ is trivial, we have $H^1(G,{\mathbb Z})\cong \mathrm{Hom}(G,{\mathbb Z}) \cong 0$.

	It follows from \ref{lem:Tate_cohomology_is_cohomology_or_homology}
	that $H^0_{\mathrm{Tate}}(G,{\mathbb Z}) \cong {\mathbb Z}/n{\mathbb Z}$.
	Hence by periodicity there is an isomorphism $H^2(G,{\mathbb Z}) \cong {\mathbb Z}/ n{\mathbb Z}$.
\end{proof}

n31867.content:
\begin{definition} \label{def:local_inv}
	\lean{localInv}
	\leanok

	Let $G$ be a finite cyclic group of order $n$ generated by an element $\mathrm{gen}$.
	Then the map
	\begin{align*}
		\mathrm{inv}_G : H^2(G,{\mathbb Z}) & \to {\mathbb Z}/n{\mathbb Z}\\
		\sigma & \mapsto \sum_{i=0}^{n-1} \sigma(\mathrm{gen}^i,\mathrm{gen})
	\end{align*}
	is called the \emph{local invariant} of $G$.
\end{definition}

n31868.content:
\begin{lemma} \label{lem:local_inv_iso}
	\lean{carry, carryCocycle, localInv, localInvIso, localInv_symm_apply}
	\leanok

	Let $G$ be a finite cyclic group of order $n$ generated by an element $\mathrm{gen}$.
	The local invariant $\mathrm{inv}_G : H^2(G,{\mathbb Z}) \to {\mathbb Z}/n{\mathbb Z}$ is an isomorphism.
	The pre-image of $1 \in {\mathbb Z}/n{\mathbb Z}$ is the cohomology class of the cocycle
	\[
		\sigma_G (\mathrm{gen}^i, \mathrm{gen}^j) = \begin{cases}
			1 & i+j \ge n \\
			0 & i+j < n,
		\end{cases}
		\qquad 0 \le i,j < n.
	\]
\end{lemma}

n31870.content:
\begin{definition}
  \label{def:herbrand_quotient}
  \uses{def:Tate_cohomology}
	\lean{Representation.herbrandQuotient, Rep.herbrandQuotient}
  \leanok
	Let $G$ be a finite cyclic group and $M$ a representation of $G$.
	Recall that there are isomorphisms $H^n_{\mathrm{Tate}}(G,M) \cong H^{n+2}_{\mathrm{Tate}}(G,M)$.
	We define the Herbrand quotient of $M$ to be
	\[
		h(G,M) = \frac{|H^0_{\mathrm{Tate}}(G,M)|}{|H^1_{\mathrm{Tate}}(G,M)|}.
	\]
	If either of the two cohomology groups are infinite then $h(G,M)$ defaults to $0$.
\end{definition}

n31871.content:
\begin{example}
  \label{eg:herbrand_Z}
	\uses{lem:H2_cyclic_Z}
  \lean{Representation.herbrandQuotient_trivial_int_eq_card,
    Rep.herbrandQuotient_trivial_int_eq_card}
  \leanok
	If $G$ is a cyclic group and ${\mathbb Z}$ has the trivial action of $G$ then $h(G,{\mathbb Z}) = |G|$.
	This follow immediately from \ref{lem:H2_cyclic_Z}.
\end{example}

n31873.content:
\begin{proof}
  \leanok
	Let $\mathrm{gen}$ be a generator of $G$.
	Recall that $H^0_{\mathrm{Tate}}(G,M) \cong M^G / N_GM$.
	Also, we can write $M^G$ as $\ker(1-\mathrm{gen}: M \to M)$.
	Similarly $H^{-1}_{\mathrm{Tate}}(G,M)$ is isomorphic to $\ker (N_G : M \to M) / \mathrm{im}(1-\mathrm{gen}: M \to M)$.
	The result follows because
	\begin{align*}
		|\ker(N_G : M \to M)| \cdot |\mathrm{im}(N_G : M \to M)|
		&=|M|\\
		&=|\ker(1-g : M \to M)| \cdot |\mathrm{im}(1-g : M \to M)|.
	\end{align*}
\end{proof}

n31874.content:
\begin{lemma}
  \label{lem:herbrand_ses}
  \uses{def:herbrand_quotient}
  \lean{Rep.herbrandQuotient_ne_zero_of_shortExact₁, Rep.herbrandQuotient_ne_zero_of_shortExact₂,
    Rep.herbrandQuotient_ne_zero_of_shortExact₃, Rep.herbrandQuotient_eq_of_shortExact}
  \leanok
	Suppose we have a short exact sequence of representations of a finite cyclic group $G$:
	\[
		0 \to A \to B \to C \to 0.
	\]
	If two of the representations $A$, $B$, $C$ have non-zero Herbrand quotient then so
	does the third, and $h(G,B) = h(G,A) \cdot h(G,C)$.
\end{lemma}

