\begin{theorem} \label{thm:trivial_cohomology_implies_trivial_Tate}
	\lean{Rep.tateCohomology_of_trivialCohomology,
		Rep.trivialHomology_of_trivialCohomology}
	\uses{cor:up_and_down_trivial_cohomology, cor:Tate_up_down_isos, lem:Tate_cohomology_is_cohomology_or_homology}
	Let $M$ be a representation of a finite group $G$, and assume that $M$ has trivial cohomology.
	Then $M$ has trivial Tate cohomology.
\end{theorem}

n31885.content:
\begin{lemma} \label{lem:splits_in_splitting_module}
	\uses{def:splitting_module}
	The image of $\sigma'$ in $H^2(G,\mathrm{split}(\sigma))$ is zero.
\end{lemma}

n31888.content:
\begin{remark}
	\begin{itemize}
		\item Given $G$ and $R$, there can be several nonisomorphic $M$ which are
  		finite class formations. For example if $M$ is a finite class formation then so is
	  	$M\oplus N$ where $N$ is any cohomologically trivial module.
	  \item I know of no example in class field theory where $R$ is any ring other than ${\mathbb Z}$.
	\end{itemize}
\end{remark}

n31890.content:
\begin{lemma} \label{lem:linear_injective_of_surjective}
	\mathlibok
	Let $I$ be an ideal of a commutative ring $R$ and let $f:R/I \to R/I$
	be a surjective $R$-linear map.
	Then $f$ is injective.
\end{lemma}

n31892.content:
\begin{remark} In the case $R={\mathbb Z}$ and $I\not=0$, which is the only case
	we shall use in applications, the lemma can just be proved by counting.
\end{remark}

n31893.content:
\begin{lemma} \label{lem:restriction_fundamental_class_generates}
	\uses{def:fundamental_class}
	Let $\sigma \in H^2(G,M)$ be a fundamental class.
	Then the restriction of $\sigma$ to any subgroup $S$ of $G$
	is a generator for $H^2(S,M)$.
\end{lemma}

n31896.content:
\begin{theorem} \label{thm:splitting_module_trivial}
	\uses{lem:restriction_fundamental_class_generates, lem:splits_in_splitting_module, thm:triviality_criterion, lem:linear_injective_of_surjective, def:cohomology_long_exact_sequence}
	Let $\sigma'$ be a 2-cocycle representing a fundamental class in $H^2(G,M)$.
	Then $\mathrm{split}(\sigma')$ has trivial cohomology.
\end{theorem}

n31898.content:
\begin{definition}
  \label{def:reciprocity_iso}
	\uses{thm:splitting_module_trivial, lem:Tate_-1_aug, thm:trivial_cohomology_implies_trivial_Tate}
	\lean{Rep.split.reciprocityIso}
  The theorem implies that we have isomorphisms for all $n\in {\mathbb Z}$ (which depend on $\sigma$):
	\[
		H^{n}_{\mathrm{Tate}}(G,\mathrm{aug}(R,G)) \cong H^{n+1}_{\mathrm{Tate}}(G,M) .
	\]
	In particular in the case $n = -1$ we have the reciprocity isomorphism
	\[
		\begin{matrix}
			G^{\mathrm{ab}} \otimes R & \cong & H^{-1}_{\mathrm{Tate}}(G,\mathrm{aug}(R,G)) &\cong&  H^0_{\mathrm{Tate}}(G,M), \\
			gG' \otimes 1 & \mapsto & [g] - [1] & \mapsto & \delta ([g] - [1])
		\end{matrix}.
	\]
	Here $\delta$ is the connecting map for the short exact sequence \ref{eq:split_ses}.
\end{definition}

n31899.content:
\begin{lemma} \label{lem:reciprocity_formula}
	\uses{def:reciprocity_iso, cor:cohomology_G-torsion}
	The reciprocity isomorphism for a fundamental class $\sigma \in H^2(G,M)$ is given by
	\[
		\mathrm{reciprocity}(gG' \otimes 1) \equiv  \sum_{x \in G} \sigma'(x,g) \bmod N_G M.
	\]
	This depends only on the cohomology class $\sigma$ rather than the cocycle $\sigma'$.
\end{lemma}

n31903.content:
\begin{definition} \label{def:norm_submodule}
	\uses{def:corestriction, lem:subgroup_compatibility}
	For a finite subgroup $S$ of $G$, we shall call $N_{G/S}M^S$ the \emph{norm submodule}
	corresponding to $S$. This is a submodule of $M^G$ containing $N_G M$.
	By the commutative diagram in \ref{lem:subgroup_compatibility},
	the image of $SG'/G' \otimes R$ under the reciprocity map is equal to
	$N_{G/S}(M^S) / N_G M$.
\end{definition}

n31904.content:
\begin{corollary} \label{cor:norm_submodule_mono}
	\uses{def:norm_submodule}
	Let $({\mathbb Z},G,M)$ be a finite class formation
	and let $S_1$ and $S_2$ be two subgroups of $G$.
	Then $S_1 G' \subseteq S_2 G'$ if and only if
	$N_{G/S_1}(M^{S_1}) \subseteq N_{G/S_2}(M^{S_2})$.
\end{corollary}

n31905.content:
\begin{corollary}[Norm Limitation Theorem] \label{cor:norm_limitiation}
	\uses{def:norm_submodule}
	Let $(R,G,M)$ be a finite class formation. Then
	\[
		N_G M = N_{G/G'} (M^{G'}).
	\]
\end{corollary}

n31906.content:
\begin{corollary} \label{cor:abelian_norm_submodule_mono}
	\uses{def:norm_submodule}
	Suppose $({\mathbb Z},G,M)$ is a finite class formation with $G$ abelian.
	Let $S_1$ and $S_2$ be subgroups of $G$.
	Then $S_1 \subseteq S_2$ if and only if $N_{G/S_1}(M^{S_1}) \subseteq N_{G/S_2}(M^{S_2})$
\end{corollary}

n31907.content:
\begin{theorem}\label{thm:hilbert_90}
	\mathlibok
	Let $l/k$ be a finite Galois extension of fields.
	Then $H^1(l/k, l^\times) \cong 0$.
\end{theorem}

n31909.content:
\begin{theorem}\label{thm:additive_field_trivial}
	\lean{Rep.iso_ind₁}
	\leanok
	\uses{lem:induced_trivial_Tate}
	Let $l/k$ be a finite Galois extension of fields.
	Then there is an isomorphism of $\mathrm{Gal}(l/k)$-representations:
	\[
		l \cong \mathrm{ind}_1(k).
	\]
	In particular $l$ has trivial Tate cohomology as a representation of $\mathrm{Gal}(l/k)$.
\end{theorem}

n31914.content:
\begin{lemma}\label{lem:serre_cor}
	Let $l/k$ be a finite Galois extension of local fields.
	There is a Galois-invariant open subgroup $M \subseteq {\mathcal O}_l^\times$
	such that $H^{q+1}(l/k,M)=0$ for all naturals $q$.
\end{lemma}

n31916.content:
\begin{lemma}\label{lem:herbrand_local_units}
	\uses{lem:serre_cor, lem:herbrand_finite, lem:herbrand_ses}
	If $l/k$ is a cyclic extension then $h(l/k, {\mathcal O}_l^\times) = 1$.
\end{lemma}

n31918.content:
\begin{lemma} \label{lem:herbrand_local_l*}
	\uses{lem:herbrand_local_units, eg:herbrand_Z, lem:herbrand_ses}
	If $l/k$ is a cyclic extension of local fields
	then $h(l/k, l^\times)= [l:k]$.
\end{lemma}

n31919.content:
\begin{proof}
	We have a short exact sequence of representations
	\[
		0 \to {\mathcal O}_l^\times \to l^\times \to {\mathbb Z}\to 0,
 	\]
	where the second map is the valuation.
	We've shown in \ref{lem:herbrand_local_units}, \ref{eg:herbrand_Z}
	that $h(l/k,{\mathcal O}^\times)=1$ and $h(l/k,{\mathbb Z}) = [l:k]$.
	Therefore $h(l/k,l^\times) = [l:k]$.
\end{proof}

n31920.content:
\begin{lemma} \label{lem:local_H2_l*}
	\uses{lem:herbrand_local_l*, thm:hilbert_90}
	If $l/k$ is a cyclic extension of local fields
	then $|H^2(l/k,l^\times)| = [l:k]$.
\end{lemma}

n31922.content:
\begin{theorem} \label{lem:local_H2_upper_bound}
	\uses{thm:hilbert_90, thm:inflation_restriction_sequence, lem:local_H2_l*, cor:cohomology_G-torsion, cor:cohomology_sub_Sylow, lem:Hn_unit}
	Let $l/k$ be a Galois extension of local fields.
	Then $|H^2(l/k,l^\times)| \le [l:k]$.
\end{theorem}

n31924.content:
\begin{lemma} \label{lem:finite_field_trivial}
	\uses{thm:additive_field_trivial, cor:periodic_cohomology, lem:herbrand_finite, thm:hilbert_90}
	The Galois modules ${\mathbb F}_l$ and ${\mathbb F}_l^\times$ have trivial cohomology.
\end{lemma}

n31926.content:
\begin{lemma} \label{lem:unramified_additive_trivial}
	\uses{thm:additive_field_trivial}
	If $l/k$ is unramified then there is a normal basis for ${\mathcal O}_l$ over ${\mathcal O}_k$.
	Hence there is an isomorphism of Galois representations ${\mathcal O}_l \cong \mathrm{ind}_1 {\mathcal O}_k$.
	In particular ${\mathcal O}_l$ has trivial cohomology.
\end{lemma}

n31927.content:
\begin{proof}
	By \ref{thm:additive_field_trivial}
	we may choose $x_0 \in {\mathbb F}_l$
	such that $\{g \bullet x_0 :g \in \mathrm{Gal}(l/k)\}$ is a normal basis.
	Let $y \in {\mathcal O}_l$ be a lift of $x_0$.
	It follows from Nakayama's lemma that $\{g \bullet y\}$ is a normal basis	in ${\mathcal O}_l$.
	As in earlier proofs, this implies the isomorphism ${\mathcal O}_l \cong \mathrm{ind}_1 {\mathcal O}_k$.
\end{proof}

n31928.content:
\begin{lemma}	\label{lem:unramified_units_trivial}
	\uses{lem:serre_approx, lem:finite_field_trivial}
	If $l/k$ is unramified then ${\mathcal O}_l^\times$ has trivial group cohomology.
\end{lemma}

n31930.content:
\begin{corollary} \label{cor:cohomology_unramified_iso_cohomology_Z}
	\uses{lem:unramified_units_trivial}
	Let $l/k$ be an unramified extension of local fields.
	Then there are isomorphisms
	\[
		H^\bullet_{\mathrm{Tate}}(l/k,l^\times) \cong H^\bullet_{\mathrm{Tate}} (l/k,{\mathbb Z})
	\]
	defined by the valuation map $v : l^\times \to {\mathbb Z}$.
	The inverse map is defined by $n \mapsto \pi_k^n$, and does not depend on the choice of $\pi_k$.
\end{corollary}

n31931.content:
\begin{proof}
	This follows from the long exact sequence using \ref{lem:unramified_units_trivial}.
\end{proof}

n31932.content:
\begin{lemma} \label{lem:unramified_fundamental_class}
	\uses{cor:cohomology_unramified_iso_cohomology_Z, lem:H2_cyclic_Z}
	Let $l/k$ be an unramified cyclic extension of local fields.
	Then $H^2(l/k,l^\times)$ is cyclic of order $[l:k]$.
	It is generated by the cohomology class of the following 2-cocycle
	\[
		\sigma_{l/k} (F_k^r, F_k^s) =
		\begin{cases}
			1 & r + s < [l:k], \\
			\pi_k & r + s \ge [l:k].
		\end{cases}
	\]
	Here $F_k$ is the Frobenius element generating $\mathrm{Gal}(l/k)$ and $r$ and $s$
	are chosen to be integers in the range $0 \le r,s <[l:k]$.
	It follows that $l / k$ is a finite class formation and $\sigma_{l/k}$ is a fundamental class.
\end{lemma}

n31933.content:
\begin{proof}
	This follows from \ref{cor:cohomology_unramified_iso_cohomology_Z}
	together with the description of $H^2(l/k,{\mathbb Z})$ in \ref{lem:H2_cyclic_Z}.
\end{proof}

n31934.content:
\begin{lemma} \label{lem:local_unramified_reciprocity}
	\uses{lem:unramified_fundamental_class, lem:reciprocity_formula}
	Let $l/k$ be a finite unramified extension of local fields and let $F_k$ be the Frobenius
	element in $\mathrm{Gal}(l/k)$. Let $\pi_k$ be a uniformizer of $k$. Then we have
	\[
		\mathrm{reciprocity}(F_k)= \pi_k,
	\]
	where the reciprocity map is defined by the fundamental class $\sigma_{l/k}$.
\end{lemma}

n31936.content:
\begin{definition} \label{def:unramified_local_inv}
	\uses{lem:unramified_units_trivial, def:local_inv}

	The \emph{local invariant} $\mathrm{inv}_{l/k} : H^2(l/k, l^\times) \cong \frac{1}{[l:k]}{\mathbb Z}/ {\mathbb Z}$ is the
	composition of the isomorphism $H^2(l/k, l^\times) \cong H^2(l/k, {\mathbb Z})$
	from \ref{lem:unramified_units_trivial} with the local invariant
	$\mathrm{inv}_{\mathrm{Gal}(l/k)} : H^2(l/k, {\mathbb Z}) \cong \frac{1}{[l:k]}{\mathbb Z}/ {\mathbb Z}$ from \ref{def:local_inv} with
  generator the Frobenius.
\end{definition}

n31937.content:
\begin{lemma} \label{lem:local_inv_fundamental_class}
	\uses{lem:unramified_fundamental_class, def:local_inv}
	The fundamental class $\sigma_{l/k}$ has local invariant $\frac{1}{[l:k]}$.
\end{lemma}

n31939.content:
\begin{lemma} \label{lem:local_unram_rest}
	\uses{lem:unramified_fundamental_class}
	Let $m / l / k$ be an unramified tower of extensions of local fields
	Then the restriction to $m/l$ of $\sigma_{m/k}$ is $\sigma_{m/l}$.
\end{lemma}

n31941.content:
\begin{lemma} \label{lem:local_unram_inv_infl}
	\uses{def:local_inv, lem:local_inv_fundamental_class}
	Let $m / l / k$ be a tower of unramified extensions of local fields
	and let $\mathrm{infl}: H^2(l/k,l^\times) \to H^2(m/k,m^\times)$ be the inflation map.
	Then
	\[
		\mathrm{inv}_{m/k} \circ \mathrm{infl}= \mathrm{inv}_{l/k}.
	\]
	In particular $\mathrm{infl}(\sigma_{l/k}) = [m:l]\cdot \sigma_{m/k}$.
\end{lemma}

n31943.content:
\begin{theorem} \label{thm:local_fund_class}
	\uses{lem:unramified_fundamental_class, thm:hilbert_90, def:local_inv, lem:local_H2_upper_bound}
	For every finite Galois extension $l/k$ of local fields, $({\mathbb Z},\mathrm{Gal}(l/k),l^\times)$ is a finite
	class formation. The element $\sigma_{l/k}$ defined above is a fundamental class.
	Corresponding the $\sigma_{l/k}$ there is a reciprocity isomorphism
	\[
		\mathrm{Gal}(l/k) \cong k^\times / N(l^\times).
	\]
\end{theorem}

n31945.content:
\begin{theorem} \label{thm:local_norm_limitation}
	\uses{cor:norm_limitiation, thm:local_fund_class}
	Let $l/k$ be a finite Galois extension of local fields and let $l^{\mathrm{ab}}$ be the
	maximal subfield of $l$ which is an abelian extension of $k$, i.e. the fixed field of
	the commutator subgroup of $\mathrm{Gal}(l/k)$.
	Then $N_{l/k}(l^\times) = N_{l^\mathrm{ab}/k}(l^{\mathrm{ab}\times})$.
\end{theorem}

n31947.content:
\begin{theorem} \label{lem:local_abelian_classification}
	\uses{thm:local_fund_class, cor:norm_submodule_mono}
	Let $l_1$ and $l_2$ be two abelian extensions of $k$ contained in a field $m$.
	Then $l_1 \subseteq l_2$ if and only if $N_{l_1/k}(l_1^\times) \supseteq N_{l_2/k}(l_2^\times)$
	and $l_1 = l_2$ if and only if $N_{l_1/k}(l_1^\times) = N_{l_2/k}(l_2^\times)$.
\end{theorem}

n31949.content:
\begin{lemma} \label{lem:norm_composite_intersection}
	\uses{thm:local_fund_class, lem:subgroup_compatibility}
	Let $l/k$ be a finite abelian extension and let $m_1$ and $m_2$ be two intermediate
	fields between $k$ and $l$ such that $l = m_1 m_2$.
	Then we have
	\[
		N_{l/k}(l^\times) = N_{m_1/k} (m_1^\times) \cap N_{m_2/k} (m_2^\times).
	\]
\end{lemma}

n31951.content:
\begin{lemma} \label{lem:local_unramified_norms}
	\uses{lem:unramified_fundamental_class}
	Let $l/k$ be an unramified extension of local fields of degree $f$.
	Then $N(l^\times) = \pi_k^{f{\mathbb Z}} \times {\mathcal O}_k^\times$.
\end{lemma}

n31953.content:
\begin{lemma} \label{lem:local_image_inertia}
	\uses{lem:subgroup_compatibility, lem:local_unramified_norms}
	Let $l/k$ be a finite abelian extension of local fields and let $I \subseteq \mathrm{Gal}(l/k)$ be
	the inertia subgroup.
	Then the image of $I$ in $k^\times / N(l^\times)$
	is the subgroup ${\mathcal O}_k^\times / N({\mathcal O}_l^\times)$.
\end{lemma}

n31957.content:
\begin{lemma} \label{lem:local_cyclotomic_norms}
	\uses{thm:local_fund_class, lem:local_isomorphism}
	Let $l = {\mathbb Q}_p(\zeta)$ where $\zeta$ is a primitive $p^n$-th root of unity
	for some $n > 0$.
	Then $N(l^\times) = p^{\mathbb Z}\times (1+p^n {\mathbb Z}_p)$.
\end{lemma}

n31959.content:
\begin{theorem} \label{thm:local_Kronecker_Weber}
	\uses{lem:local_cyclotomic_norms}
	Let $l/{\mathbb Q}_p$ be a finite abelian extension.
	Then $l$ is isomorphic to a subfield of a cyclotomic extension.
\end{theorem}

n31961.content:
\begin{theorem} \label{thm:Kronecker_Weber}
	\uses{lem:local_cyclotomic_norms, lem:local_image_inertia, lem:subgroup_compatibility}
	Let $l/{\mathbb Q}$ be a finite abelian extension.
	Then there exists a natural number $n$ such that $l$ is isomorphic to
	a subfield of ${\mathbb Q}(\zeta_n)$.
\end{theorem}

n31963.content:
\begin{lemma} \label{lem:idele_class_invariants}
	\uses{thm:hilbert_90}
	Let $l/k$ be a finite Galois extension of number fields (or even global fields).
	The map $\mathrm{Cl}_k \to \mathrm{Cl}_l ^ {\mathrm{Gal}(l/k)}$ is an isomorphism.
\end{lemma}

n31967.content:
\begin{lemma} \label{lem:cohomology_S-ideles_decomp}
	\uses{lem:Shapiro, lem:semi-local_iso_coind, lem:unramified_units_trivial}
	There are isomorphisms for all $n > 0$
	\[
		H^n(l/k, {\mathbb A}_{S,l}^\times)
		\cong
		\prod_{v \in S} H^n(l_{\hat v} / k_v, l_{\hat v}^\times).
	\]
\end{lemma}

n31969.content:
\begin{lemma} \label{lem:herbrand_S-ideles}
	\uses{lem:cohomology_S-ideles_decomp, lem:herbrand_local_l*}
	If $l/k$ is a cyclic extension then we have
	\[
		h(l/k, {\mathbb A}_{S,l} ^\times )
		=
		\prod_{v \in S} |D_{\hat v}|.
	\]
\end{lemma}

n31971.content:
\begin{lemma} \label{lem:herbrand_L_S}
	\uses{lem:Shapiro, lem:H2_cyclic_Z}
	If $l/k$ is a cyclic extension then
	$h(l/k,L_S) = \prod_{v \in S} |D_{\hat v}|$.
\end{lemma}

n31972.content:
\begin{proof}
	This follows from Shapiro's lemma (\ref{lem:Shapiro})
	together with the calculation
	of the cohomology of a cyclic group with values in ${\mathbb Z}$ (\ref{lem:H2_cyclic_Z}).
\end{proof}

n31973.content:
\begin{lemma} \label{lem:herbrand_log_lattice}
	\uses{lem:herbrand_L_S, lem:herbrand_ses, lem:herbrand_finite}
	Let $l/k$ be cyclic and let $M$ be any Galois-invariant lattice in $V_S$.
	Then $h(l/k,M) = \prod_{v \in S} |D_{\hat v}|$
\end{lemma}

n31974.content:
\begin{proof}
	The representations $M \otimes {\mathbb Q}$ and $L_S \otimes {\mathbb Q}$ have the same character
	(this is just the character of the representation $V_S$).
	Therefore the representations $M \otimes {\mathbb Q}$ and $L_S \otimes {\mathbb Q}$ are isomorphic.
	Hence $M$ is isomorphic to subrepresentation of finite index in $L_S$,
	so by \ref{lem:herbrand_ses} and \ref{lem:herbrand_finite}
	they have the same Herbrand quotient.
	The result then follows from \ref{lem:herbrand_L_S}.
\end{proof}

n31975.content:
\begin{theorem} \label{thm:Dirichlet_unit_theorem}
	%\lean{NumberField.Units.dirichletUnitTheorem.unitLattice_span_eq_top}
	%\mathlibok
	$\log_S({\mathcal O}_S^\times)$ has zero intersection with $\mathrm{Span}(1,1,\ldots,1)$.
	The direct sum of these subrepresentations is a lattice in $V_S$.
\end{theorem}

n31976.content:
\begin{proof}
	%\mathlibok
