n31982.content:
\begin{lemma} \label{lem:Dirichlet_density_union}
	\uses{def:Dirichlet_density}
	Suppose $M_1$ and $M_2$ are disjoint sets of primes of ${\mathcal O}_l$.
	If two of the sets $M_1, M_2, M_1 \cup M_2$ have a Dirichlet density, then so does the third
	and we have
	\[
		\mathrm{density}(M_1 \cup M_2) = \mathrm{density}(M_1) + \mathrm{density}(M_2).
	\]
\end{lemma}

n31984.content:
\begin{lemma} \label{lem:Dirichlet_density_top}
	\uses{def:Dirichlet_density}
	The set of all primes of ${\mathcal O}_k$ has Dirichlet density $1$.
\end{lemma}

n31986.content:
\begin{lemma} \label{lem:Dirichlet_density_degree_one}
	\uses{lem:Dirichlet_density_top, lem:Dirichlet_density_union}
	The set of primes of ${\mathcal O}_l$ of degree one has Dirichlet density $1$.
\end{lemma}

n31988.content:
\begin{lemma} \label{lem:Dirichlet_density_split}
	\uses{lem:Dirichlet_density_degree_one}
	Let $l/k$ be a finite Galois extension of number fields.
	Then the set of degree $1$ primes of $k$ which split completely in $l$
	has density $\frac{1}{[l:k]}$.
\end{lemma}

n31991.content:
\begin{proof}
	We have
	\begin{align*}
		\mathrm{Cl}_{k} / N(\mathrm{Cl}_l)
		& \cong {\mathbb A}_{k,S}^\times / {\mathcal O}_{k,S}^\times N({\mathbb A}_{l,S}^\times) \\
		& \cong \left(\prod_{v \in S} k_v^\times / N(l_{\hat v}^\times)\right) / {\mathcal O}_{k,S}^\times,
	\end{align*}
	where $\hat v$ is a place of $l$ lying above $v$.
	The result follows because each of the groups $k_v^\times / N(l_w)$ is finite
	(in fact by the local reciprocity isomorphism this is isomorphic to the abelianization of the
	decomposition group at $\hat v$).
\end{proof}

n31993.content:
\begin{lemma}[Weak lemma] \label{lem:L-function_bound}
	\uses{def:L-function}
	If $\chi$ is a non-trivial character then $L(s,\chi)$ is
	bounded on the interval $(1,2)$.
\end{lemma}

n31994.content:
\begin{lemma} \label{lem:density_bound}
	\uses{lem:L-function_bound}
	Let $M$ be a set of primes of ${\mathcal O}_S$ whose image in $H^0_{\mathrm{Tate}}(l/k,\mathrm{Cl}_l)$ is zero.
	There exists a real number $c$ depending only on the fields $k$ and $l$,
	such that for all $s > 1$ we have:
	\[
		\sum_{p \in M} N(P)^{-s}
		\le \frac{1}{|H^0_{\mathrm{Tate}}(l/k,\mathrm{Cl}_l)|} \log\left(\frac{1}{s-1}\right) + c.
	\]
\end{lemma}

n31995.content:
\begin{proof}
	Let $s > 1$. All the series in the following calculation converge absolutely in this region.
	The implied constants in the $O(1)$ terms do not depend on $s$.
	\begin{align*}
		\sum_{P \in M} |N(P)|^{-s}
		&= \frac{1}{|H^0_{\mathrm{Tate}}(l/k,\mathrm{Cl}_l)|} \sum_P \sum_\chi \chi(P) N(P)^{-s}\\
		&= \frac{1}{|H^0_{\mathrm{Tate}}(l/k,\mathrm{Cl}_l)|}
		\sum_P \sum_\chi -\log(1-\chi(P) N(P)^{-s}) + O(1)\\
		&= \frac{1}{|H^0_{\mathrm{Tate}}(l/k,\mathrm{Cl}_l)|}
		\sum_P \sum_\chi -\log |1-\chi(P) N(P)^{-s}| + O(1)\\
		&= \frac{1}{|H^0_{\mathrm{Tate}}(l/k,\mathrm{Cl}_l)|}
		\sum_\chi \sum_P -\log |1-\chi(P) N(P)^{-s}| + O(1)\\
		&= \frac{1}{|H^0_{\mathrm{Tate}}(l/k,\mathrm{Cl}_l)|} \log \left(\prod_\chi |L(s,\chi)| \right) + O(1)\\
		&\le \frac{1}{|H^0_{\mathrm{Tate}}(l/k,\mathrm{Cl}_l)|} \log \left(\frac{1}{s-1}\right) + O(1).
	\end{align*}
	Interchanging the order of summation is justified because the series converge absolutely.
	We need to be slightly careful about which branch of the logarithm we are using here.
	In the expression $\log(1-\chi(P) N(P)^{-s})$ we shall mean the branch which is continuous
	on the ball of radius $1$, centred about $1$.
	The imaginary parts of $\log(1-\chi(P) N(P)^{-s})$ and $\log(1-\bar \chi(P) N(P)^{-s})$
	cancel out; this justifies replacing $\log(1-\chi(P) N(P)^{-s})$ by $\log |1-\chi(P) N(P)^{-s}|$.
\end{proof}

n31997.content:
\begin{theorem} \label{thm:first_inequality}
	\uses{lem:Dirichlet_density_split, lem:density_bound}
	For any finite Galois extension $l/k$ be have
	\[
		|H^0_{\mathrm{Tate}}(l/k, \mathrm{Cl}_{l}) | \le [l : k].
	\]
\end{theorem}

n31999.content:
\begin{corollary} \label{cor:H1_H2_cyclic_idele_class}
	\uses{thm:first_inequality, lem:herbrand_idele_class_group}
	If $l/k$ is cyclic then $|H^2(l/k, \mathrm{Cl}_{l})| = [l:k]$ and $H^1(l/k, \mathrm{Cl}_{l}) = 0$.
\end{corollary}

n32000.content:
\begin{proof}
	This follows immediately from (a) the first inequality, (b) the periodicity of
	the cohomology for a cyclic group, and (c) the calculation of the Herbrand quotient
	of $\mathrm{Cl}_{l}$.
\end{proof}

n32001.content:
\begin{theorem} \label{thm:global_cohomology_bound}
	\uses{cor:H1_H2_cyclic_idele_class, thm:inflation_restriction_sequence, cor:cohomology_sub_Sylow, cor:cohomology_G-torsion}
	If $l/k$ is any finite Galois extension then $H^1(l/k, \mathrm{Cl}_{l}) \cong 0$
	and $|H^2(l/k, \mathrm{Cl}_{l})| \le [l:k]$.
\end{theorem}
